<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {matSearch,matClose,matArrowBack,matArrowForward} from '@quasar/extras/material-icons'
import {request} from '../lib/api'
interface Model {id:string;brand:string;brand_key:string;model:string;type:string;megapixels:number|null;resolution:string;protocols:string[]}
interface Profile {id:string;label:string;path:string;port:number;codec:string;source:string;notes:string}
interface Meta {manifest:{models:number;brands:number;profiles:number;revision:string;license:string};brands:{key:string;name:string;count:number}[]}
const props=withDefaults(defineProps<{initialSearch?:string}>(),{initialSearch:''})
const meta=ref<Meta|null>(null),rows=ref<Model[]>([]),total=ref(0),search=ref(props.initialSearch),brand=ref(''),protocol=ref(''),offset=ref(0),size=ref(10),loading=ref(false),error=ref(''),selected=ref<Model|null>(null),detail=ref<Record<string,unknown>|null>(null),profiles=ref<Profile[]>([]),detailLoading=ref(false),detailError=ref('')
let listAbort:AbortController|undefined,detailAbort:AbortController|undefined
const count=(n:number)=>new Intl.NumberFormat().format(n)
async function load(){listAbort?.abort();const c=new AbortController();listAbort=c;loading.value=true;error.value='';try{const p=await request<{items:Model[];total:number}>(`/catalogue/models?search=${encodeURIComponent(search.value)}&brand=${encodeURIComponent(brand.value)}&protocol=${encodeURIComponent(protocol.value)}&limit=${size.value}&offset=${offset.value}`,{signal:c.signal});if(c.signal.aborted)return;rows.value=p.items;total.value=p.total}catch(e){if(!c.signal.aborted)error.value=e instanceof Error?e.message:'Catalogue unavailable'}finally{if(!c.signal.aborted)loading.value=false}}
function filter(){offset.value=0;void load()}
async function open(model:Model){detailAbort?.abort();const c=new AbortController();detailAbort=c;selected.value=model;detail.value=null;profiles.value=[];detailLoading.value=true;detailError.value='';try{const [d,p]=await Promise.all([request<Record<string,unknown>>('/catalogue/models/'+encodeURIComponent(model.id),{signal:c.signal}),request<{items:Profile[]}>('/catalogue/profiles?brand='+encodeURIComponent(model.brand_key),{signal:c.signal})]);if(c.signal.aborted)return;detail.value=d;profiles.value=p.items}catch(e){if(!c.signal.aborted)detailError.value=e instanceof Error?e.message:'Specifications unavailable'}finally{if(!c.signal.aborted)detailLoading.value=false}}
function close(){detailAbort?.abort();selected.value=null;detail.value=null;profiles.value=[]}
function safeLink(value:unknown){if(typeof value!=='string')return '';try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:''}catch{return ''}}
const sources=computed(()=>Array.isArray(detail.value?.sources)?detail.value!.sources.map(safeLink).filter(Boolean):[])
const label=(key:string)=>key.replace(/_/g,' ').replace(/\b(ip|rtsp|onvif|ndaa|poe|ptz|ir|fov|ik|sd)\b/gi,s=>s.toUpperCase())
function flatten(value:unknown,prefix=''):Array<{key:string;value:string}>{
 if(value===null||value===undefined)return []
 if(Array.isArray(value))return value.every(x=>typeof x!=='object')?[{key:prefix,value:value.map(String).join(' · ')}]:value.flatMap((v,i)=>flatten(v,`${prefix} ${i+1}`))
 if(typeof value==='object')return Object.entries(value as Record<string,unknown>).flatMap(([k,v])=>flatten(v,prefix?prefix+' / '+label(k):label(k)))
 return [{key:prefix,value:typeof value==='boolean'?(value?'Yes':'No'):String(value)}]
}
const specs=computed(()=>Object.entries(detail.value??{}).filter(([k])=>!['id','brand','model','sources','configs','last_verified'].includes(k)).flatMap(([k,v])=>flatten(v,label(k))))
watch(()=>props.initialSearch,v=>{search.value=v;filter()})
onMounted(async()=>{try{meta.value=await request<Meta>('/catalogue/meta')}catch(e){error.value=e instanceof Error?e.message:'Catalogue unavailable'}void load()})
onBeforeUnmount(()=>{listAbort?.abort();detailAbort?.abort()})
</script>
<template>
 <q-page class="console-page catalogue-page">
  <header class="page-heading"><div><span class="eyebrow">Camera intelligence</span><h1>Camera catalogue</h1><p class="helper">Reference knowledge. Device evidence stays separate.</p></div><span class="offline-label"><span/> Available offline</span></header>
  <div v-if="meta" class="catalogue-summary"><strong>{{count(meta.manifest.models)}} <small>models</small></strong><span>{{count(meta.manifest.brands)}} brands</span><span>{{count(meta.manifest.profiles)}} documented connection references</span><span class="source-stamp">{{meta.manifest.license}} · {{meta.manifest.revision.slice(0,8)}}</span></div>
  <div v-if="error" role="alert" class="error-banner">{{error}} <q-btn flat dense label="Retry" @click="load"/></div>
  <div class="catalogue-layout" :class="{'has-detail':selected}">
   <section class="surface catalogue-list" aria-label="Camera model catalogue" :aria-busy="loading">
    <div class="catalogue-filters"><q-input v-model="search" outlined dense clearable maxlength="200" placeholder="Search brand, model or resolution" aria-label="Search camera catalogue" @keyup.enter="filter" @clear="filter"><template #prepend><q-icon :name="matSearch"/></template><template #append><q-btn flat round dense :icon="matArrowForward" aria-label="Search catalogue" @click="filter"/></template></q-input><q-select v-model="brand" outlined dense emit-value map-options label="Brand" :options="[{label:'All brands',value:''},...(meta?.brands??[]).map(b=>({label:b.name,value:b.key}))]" @update:model-value="filter"/><q-select v-model="protocol" outlined dense emit-value map-options label="Protocol" :options="[{label:'Any protocol',value:''},{label:'RTSP',value:'rtsp'},{label:'ONVIF',value:'onvif'}]" @update:model-value="filter"/></div>
    <p v-if="loading&&!rows.length" class="loading-label" role="status">Loading local catalogue…</p><p v-else-if="!rows.length" class="loading-label">No matching models. Try a broader search.</p>
    <div v-else class="resource-table-scroll"><table class="resource-table"><thead><tr><th>Model</th><th>Brand</th><th>Resolution</th><th>Protocols</th></tr></thead><tbody><tr v-for="m in rows" :key="m.id" :class="{'selected-row':selected?.id===m.id}"><td><button class="job-name model-link" data-testid="camera-model" @click="open(m)">{{m.model}}</button><small class="model-type">{{m.type||'Type not specified'}}</small></td><td>{{m.brand}}</td><td>{{m.resolution||(m.megapixels?m.megapixels+' MP':'Not specified')}}</td><td><span class="protocol-text">{{m.protocols?.join(' · ')||'Not documented'}}</span></td></tr></tbody></table></div>
    <footer class="catalogue-pagination"><span>{{total?`${offset+1}–${Math.min(offset+size,total)} of ${count(total)}`:'0 models'}}</span><q-select v-model="size" outlined dense :options="[10,25,50]" aria-label="Models per page" @update:model-value="filter"/><q-btn flat round dense :icon="matArrowBack" aria-label="Previous catalogue page" :disable="offset===0||loading" @click="offset-=size;load()"/><q-btn flat round dense :icon="matArrowForward" aria-label="Next catalogue page" :disable="offset+size>=total||loading" @click="offset+=size;load()"/></footer>
   </section>
   <aside v-if="selected" class="surface catalogue-detail" aria-label="Camera reference specifications">
    <header class="detail-heading"><div><span class="eyebrow">{{selected.brand}}</span><h2>{{selected.model}}</h2></div><q-btn flat round dense :icon="matClose" aria-label="Close model specifications" @click="close"/></header>
    <h3>Reference specifications</h3><p class="helper">Manufacturer reference data — not observed device properties.</p>
    <p v-if="detailLoading" role="status">Loading specifications…</p><p v-if="detailError" role="alert">{{detailError}}</p>
    <dl v-if="detail" class="spec-list"><template v-for="s in specs" :key="s.key"><dt>{{s.key}}</dt><dd>{{s.value}}</dd></template></dl>
    <section v-if="profiles.length" class="connection-references"><h3>Connection references</h3><p class="helper">Brand-level paths, not a promise that this exact model supports them.</p><details v-for="p in profiles" :key="p.id"><summary>{{p.label}} <span class="helper">{{p.codec}} · port {{p.port}}</span></summary><code>{{p.path}}</code><p class="helper">{{p.notes}}</p><a v-if="safeLink(p.source.match(/https?:\/\/\S+/)?.[0])" :href="safeLink(p.source.match(/https?:\/\/\S+/)?.[0])" target="_blank" rel="noopener noreferrer">Manufacturer documentation ↗</a></details></section>
    <section v-if="sources.length" class="catalogue-sources"><h3>Sources</h3><a v-for="(url,i) in sources" :key="url" :href="url" target="_blank" rel="noopener noreferrer">Source {{i+1}} ↗</a><p v-if="detail?.last_verified" class="helper">Upstream last verified: {{detail.last_verified}}</p></section>
    <router-link class="connection-link" to="/results">View automatically saved scan evidence →</router-link>
    <details v-if="detail" class="original-record"><summary>Original upstream record</summary><pre>{{JSON.stringify(detail,null,2)}}</pre></details>
   </aside>
  </div>
  <footer class="catalogue-attribution"><a href="https://github.com/ch-bas/cctv-camera-database" target="_blank" rel="noopener noreferrer">Open camera database ↗</a><span>Version-pinned, source-linked data.</span><a href="https://www.ispyconnect.com/cameras" target="_blank" rel="noopener noreferrer">iSpy reference ↗</a><span>Linked only; its database is not redistributed.</span></footer>
 </q-page>
</template>
<style scoped>
