r(--line);padding:9px 0;font-size:12px}.connection-references summary{cursor:pointer;font-weight:600}.connection-references code{display:block;background:var(--canvas);padding:10px;margin:10px 0;overflow-wrap:anywhere;white-space:pre-wrap}.catalogue-sources a{display:inline-block;margin-right:16px;font-size:12px}.connection-link{display:block;font-size:12px;font-weight:650;margin-top:24px}.original-record{margin-top:22px;font-size:11px}.original-record summary{cursor:pointer}.original-record pre{overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;max-height:350px;background:var(--canvas);padding:12px}.catalogue-attribution{display:flex;gap:10px 16px;flex-wrap:wrap;margin-top:22px;font-size:11px;color:var(--muted)}@media(max-width:1250px){.catalogue-layout.has-detail{grid-template-columns:minmax(0,1fr)}.catalogue-filters{grid-template-columns:minmax(150px,1fr) 150px 130px}}@media(max-width:600px){.catalogue-filters{grid-template-columns:1fr 1fr;padding:14px}.catalogue-filters>.q-input{grid-column:1/-1}.catalogue-summary{gap:10px 18px;padding-bottom:18px}.source-stamp{margin-left:0}.catalogue-detail{padding:18px}.offline-label{display:none}.catalogue-attribution{display:grid;grid-template-columns:1fr}.catalogue-pagination{gap:4px}}
